from pysat.formula import CNF
from pysat.solvers import Solver
from pysat.card import CardEnc

n = 12
N = 2 * n

def var(v, p):
    return (v-1)*N + p + 1

cnf = CNF()

# Each position gets exactly one value
for p in range(N):
    lits = [var(v, p) for v in range(1, n+1)]
    cnf.add_clause(lits)
    for v1 in range(1, n+1):
        for v2 in range(v1+1, n+1):
            cnf.add_clause([-var(v1, p), -var(v2, p)])

# Each value appears exactly twice
for v in range(1, n+1):
    lits = [var(v, p) for p in range(N)]
    cnf.extend(CardEnc.equals(lits, bound=2, topk=True, encoding='compact'))

# Pair variables
pair_var = {}
pair_idx = n * N + 1

for v in range(1, n+1):
    for p in range(N - v - 1):
        pair_var[(v, p)] = pair_idx
        pair_idx += 1

# Each value has exactly one pair
for v in range(1, n+1):
    pairs = [pair_var[(v, p)] for p in range(N - v - 1)]
    cnf.add_clause(pairs)
    for i in range(len(pairs)):
        for j in range(i+1, len(pairs)):
            cnf.add_clause([-pairs[i], -pairs[j]])

# Link pair variables to position variables
for v in range(1, n+1):
    for p in range(N - v - 1):
        pv = pair_var[(v, p)]
        cnf.add_clause([-pv, var(v, p)])
        cnf.add_clause([-pv, var(v, p+v+1)])
        cnf.add_clause([-var(v, p), -var(v, p+v+1), pv])

# If var(v,p) is true, then some pair must cover it
for v in range(1, n+1):
    for p in range(N):
        clause = [-var(v, p)]
        if p < N - v - 1:
            clause.append(pair_var[(v, p)])
        if p - v - 1 >= 0:
            clause.append(pair_var[(v, p - v - 1)])
        cnf.add_clause(clause)

print(f"Variables: {pair_idx-1}")
print(f"Clauses: {len(cnf.clauses)}")

solver = Solver(name='cadical')
solver.append_formula(cnf.clauses)
result = solver.solve()

print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    seq = [0] * N
    for v in range(1, n+1):
        for p in range(N):
            if model[var(v, p)-1] > 0:
                seq[p] = v
    print(f"Sequence: {seq}")

    # Verify
    ok = True
    for v in range(1, n+1):
        positions = [i for i, val in enumerate(seq) if val == v]
        if len(positions) != 2:
            print(f"Value {v}: found {len(positions)} times!")
            ok = False
        elif positions[1] - positions[0] != v + 1:
            print(f"Value {v}: positions {positions}, diff = {positions[1]-positions[0]}, expected {v+1}")
            ok = False
        else:
            print(f"Value {v}: positions {positions}, diff = {positions[1]-positions[0]} OK")
    if ok:
        print("All verified!")
else:
    print("UNSATISFIABLE")

